(()=>{'use strict';
const E=x=>(window.esc?esc(x):String(x??'')),DL=x=>(window.dateBR?dateBR(x):x),status=t=>t.status||(t.done?'completed':'pending');
function quarterBounds(key){const m=String(key||'').match(/^(\d{4})-Q([1-4])$/);if(!m)return null;const y=+m[1],q=+m[2],mo=(q-1)*3+1;return{key,label:`${q}º trimestre de ${y}`,from:`${y}-${String(mo).padStart(2,'0')}-01`,to:new Date(y,q*3,0).toISOString().slice(0,10)}}
function quarterKeys(){const dates=(state.ministeringV2?.interviews||[]).map(x=>x.date).filter(Boolean),now=new Date();dates.push(now.toISOString().slice(0,10));const keys=new Set(dates.map(d=>{const [y,m]=d.split('-').map(Number);return `${y}-Q${Math.floor((m-1)/3)+1}`}));return [...keys].sort().reverse()}
function ministeringHistory(){if(currentTab!=='Ministração'||document.querySelector('.sv3Quarter'))return;const hero=document.querySelector('#view .hero');if(!hero)return;const keys=quarterKeys(),box=document.createElement('div');box.className='sv3Quarter';box.innerHTML=`<label>Período<select data-sv3-quarter>${keys.map((k,i)=>`<option value="${k}" ${i?'':'selected'}>${quarterBounds(k).label}</option>`).join('')}</select></label><div data-sv3-summary></div>`;hero.insertAdjacentElement('afterend',box);renderQuarter(box,keys[0])}
function renderQuarter(box,key){const q=quarterBounds(key),ds=window.MINISTERING_DISTRICTS||[],ints=state.ministeringV2?.interviews||[],all=ds.flatMap(d=>d.companionships.map(c=>({d,c}))),done=all.filter(({c})=>ints.some(i=>i.companionshipId===c.id&&i.date>=q.from&&i.date<=q.to)).length,total=all.length,prevKey=(()=>{let [y,qn]=key.split('-Q').map(Number);qn--;if(qn<1){qn=4;y--}return `${y}-Q${qn}`})(),pq=quarterBounds(prevKey),prev=all.filter(({c})=>ints.some(i=>i.companionshipId===c.id&&i.date>=pq.from&&i.date<=pq.to)).length,pct=total?Math.round(done/total*100):0,pp=total?Math.round(prev/total*100):0;box.querySelector('[data-sv3-summary]').innerHTML=`<div class="sv3Stat"><b>${pct}%</b><span>${done} de ${total} companhias</span><small>${pct===pp?'Mesmo resultado':pct>pp?'+'+(pct-pp)+' p.p.':'−'+(pp-pct)+' p.p.'} em relação ao trimestre anterior</small></div>`}
function completedHistory(){if(currentTab!=='Início'||document.querySelector('.sv3History'))return;const done=(state.tasks||[]).filter(t=>status(t)==='completed').sort((a,b)=>String(b.completedAt||'').localeCompare(String(a.completedAt||''))).slice(0,8);if(!done.length)return;const root=document.getElementById('view'),box=document.createElement('details');box.className='sv3History';box.innerHTML=`<summary>Concluídas recentemente <span>${done.length}</span></summary><div>${done.map(t=>`<div class="sv3Done"><b>${E(t.title)}</b><small>${E(t.assignee||'Sem responsável')}${t.completedAt?' · '+DL(String(t.completedAt).slice(0,10)):''}</small></div>`).join('')}</div>`;root.appendChild(box)}
function run(){try{ministeringHistory();completedHistory()}catch(e){console.warn('safe bundle v3 skipped',e)}}
document.addEventListener('change',e=>{const s=e.target.closest('[data-sv3-quarter]');if(s)renderQuarter(s.closest('.sv3Quarter'),s.value)});const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);requestAnimationFrame(run);return r};document.addEventListener('DOMContentLoaded',()=>setTimeout(run,0));
const css=document.createElement('style');css.textContent=`.sv3Quarter{display:flex;align-items:end;justify-content:space-between;gap:18px;background:var(--ios-card,#fff);padding:14px 18px;border-radius:16px;margin-bottom:14px}.sv3Quarter label{margin:0;min-width:190px}.sv3Quarter select{margin:5px 0 0}.sv3Stat{text-align:right}.sv3Stat b,.sv3Stat span,.sv3Stat small{display:block}.sv3Stat b{font-size:24px;color:var(--teal);letter-spacing:-.03em}.sv3History{background:var(--ios-card,#fff);border-radius:16px;margin:14px 0;overflow:hidden}.sv3History summary{cursor:pointer;padding:16px 18px;font-weight:700;list-style:none}.sv3History summary::-webkit-details-marker{display:none}.sv3History summary span{float:right;color:var(--mut);font-weight:500}.sv3History>div{padding:0 18px 10px}.sv3Done{border-top:.5px solid var(--ios-sep,var(--line));padding:11px 0}.sv3Done b,.sv3Done small{display:block}.sv3Done b{font-size:13px}@media(max-width:600px){.sv3Quarter{align-items:stretch;flex-direction:column;gap:7px}.sv3Stat{text-align:left}}`;document.head.appendChild(css)})();